{
    "table_name": "connections",
    "function": "CREATE OR REPLACE FUNCTION live_map()\nRETURNS trigger AS\n$$\nDECLARE\n    payload                text;\n    channel                text := 'live_map';\n    account_info           jsonb;\n    source_ip_info         jsonb;\n    destination_ip_info    jsonb;\n    source_ip_text         text := TRIM(SPLIT_PART(NEW.source_ip::text, '/', 1));\n    destination_ip_text    text := TRIM(SPLIT_PART(NEW.destination_ip::text, '/', 1));\nBEGIN\n    -- Fetch account info\n    SELECT COALESCE(\n        JSONB_AGG(DISTINCT JSONB_BUILD_OBJECT(\n            'id', account.id,\n            'contact_id', account.contact_id\n        )) FILTER (WHERE account.id IS NOT NULL),\n        '[]'\n    )\n    INTO account_info\n    FROM (\n        SELECT\n            joined_account.id,\n            joined_account.contact_id\n        FROM organization_accounts AS joined_account\n        WHERE\n            joined_account.tombstone = 0 AND\n            joined_account.organization_id IS NOT NULL AND\n            joined_account.organization_id = NEW.organization_id AND\n            NEW.created_by = joined_account.id\n    ) AS account;\n\n    -- Fetch source IP info\n    SELECT JSON_BUILD_OBJECT(\n        'ip', ip_details.ip,\n        'country', ip_details.country,\n        'region', ip_details.region,\n        'city', ip_details.city\n    )\n    INTO source_ip_info\n    FROM ip_infos AS ip_details\n    WHERE TRIM(ip_details.ip) = source_ip_text\n    LIMIT 1;\n\n    -- Fetch destination IP info\n    SELECT JSON_BUILD_OBJECT(\n        'ip', ip_details.ip,\n        'country', ip_details.country,\n        'region', ip_details.region,\n        'city', ip_details.city\n    )\n    INTO destination_ip_info\n    FROM ip_infos AS ip_details\n    WHERE TRIM(ip_details.ip) = destination_ip_text\n    LIMIT 1;\n\n    -- Build JSON payload\n    SELECT JSON_BUILD_OBJECT(\n        'type', channel,\n        'change', TG_OP,\n        'id', NEW.id,\n        'account', account_info,\n        'created_by', NEW.created_by,\n        'organization_id', NEW.organization_id,\n        'source_ip', NEW.source_ip,\n        'destination_ip', NEW.destination_ip,\n        'interface_name', NEW.interface_name,\n        'total_byte', NEW.total_byte,\n        'timestamp', NEW.timestamp,\n        'event_name', channel || '-' || NEW.device_id || '-' || NEW.organization_id,\n        'ip_info', JSONB_BUILD_OBJECT(\n            'source', COALESCE(source_ip_info, 'null'::jsonb),\n            'destination', COALESCE(destination_ip_info, 'null'::jsonb)\n        )\n    )::text\n    INTO payload;\n\n    -- Send notification only if not tombstoned\n    IF NEW.tombstone = 0 THEN\n        PERFORM pg_notify(channel, payload);\n    END IF;\n\n    RETURN NEW;\nEND;\n$$\nLANGUAGE plpgsql;\n"
}